// Basic output
console.log('Hello, world!');          // white text
console.info('Page loaded');           // same as log
console.warn('Deprecated API used');   // yellow, warning icon
console.error('Fetch failed: 404');    // red, error icon, stack trace

// Structured output
console.table([                        // renders as a table
  { name: 'Alice', score: 95 },
  { name: 'Bob', score: 80 },
]);

console.dir(document.body);            // explore an object's properties

// Grouping
console.group('User data');            // collapsible group
console.log('Name: Alice');
console.log('Role: admin');
console.groupEnd();

// Timing
console.time('fetch-users');           // start timer
await fetchUsers();
console.timeEnd('fetch-users');        // prints: 'fetch-users: 84ms'

// Assertions
console.assert(user.age > 0, 'Age must be positive'); // only logs if false

// Counting
console.count('click');  // click: 1
console.count('click');  // click: 2
